{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2176-09-27 12:15:00",
      "speaker": "Doctor",
      "text": "Hi, I'm Dr. Lee. I'll be your doctor during this admission. You're here for your 23rd cycle of high-dose methotrexate for your CNS lymphoma, correct?"
    },
    {
      "turn_number": 2,
      "time": "2176-09-27 12:16:30",
      "speaker": "Patient",
      "text": "Yes, that’s right. I’ve been feeling okay since my last treatment. No headaches or weakness."
    },
    {
      "turn_number": 3,
      "time": "2176-09-27 12:17:45",
      "speaker": "Doctor",
      "text": "That’s good to hear. We’ll start by making sure your urine is alkaline before giving the methotrexate. That helps protect your kidneys."
    },
    {
      "turn_number": 4,
      "time": "2176-09-27 12:19:00",
      "speaker": "Patient",
      "text": "I remember that from last time. They gave me something in the IV to do that, right?"
    },
    {
      "turn_number": 5,
      "time": "2176-09-27 12:20:15",
      "speaker": "Doctor",
      "text": "Exactly. We’ll use sodium bicarbonate in your IV fluids. The methotrexate will be given tomorrow morning."
    },
    {
      "turn_number": 6,
      "time": "2176-09-27 12:21:30",
      "speaker": "Patient",
      "text": "Okay. Last time I felt nauseated afterward. Is that expected?"
    },
    {
      "turn_number": 7,
      "time": "2176-09-27 12:22:45",
      "speaker": "Doctor",
      "text": "It’s common. We’ll give you prochlorperazine if needed, and you can use the lorazepam you already take if nausea or anxiety comes up."
    },
    {
      "turn_number": 8,
      "time": "2176-09-27 12:24:00",
      "speaker": "Patient",
      "text": "That helps. I’m a little nervous, but I trust the process."
    },
    {
      "turn_number": 9,
      "time": "2176-09-27 12:25:15",
      "speaker": "Doctor",
      "text": "You’re doing great. We’ll monitor your labs closely, especially your kidney and liver function."
    },
    {
      "turn_number": 10,
      "time": "2176-09-27 12:26:30",
      "speaker": "Patient",
      "text": "And the methotrexate level? You check that too?"
    },
    {
      "turn_number": 11,
      "time": "2176-09-27 12:27:45",
      "speaker": "Doctor",
      "text": "Yes, we’ll check it daily until it drops low enough. Leucovorin rescue starts 24 hours after the infusion to protect your healthy cells."
    },
    {
      "turn_number": 12,
      "time": "2176-09-27 12:29:00",
      "speaker": "Patient",
      "text": "Got it. I remember that helped last time."
    },
    {
      "turn_number": 13,
      "time": "2176-09-27 12:30:15",
      "speaker": "Doctor",
      "text": "We’ll also keep an eye on your blood counts. Your hemoglobin was a bit low on admission, but stable."
    },
    {
      "turn_number": 14,
      "time": "2176-09-27 12:31:30",
      "speaker": "Patient",
      "text": "It’s always been a little low. From the chemo, I think."
    },
    {
      "turn_number": 15,
      "time": "2176-09-27 12:32:45",
      "speaker": "Doctor",
      "text": "Yes, that’s common. We call it chemotherapy-induced anemia. But you’re not needing transfusions, so that’s good."
    },
    {
      "turn_number": 16,
      "time": "2176-09-27 12:34:00",
      "speaker": "Patient",
      "text": "I take iron at home, but my doctor said not to during admission."
    },
    {
      "turn_number": 17,
      "time": "2176-09-27 12:35:15",
      "speaker": "Doctor",
      "text": "That’s right. We avoid certain supplements during chemo. You’re on docusate and senna for constipation—still taking those?"
    },
    {
      "turn_number": 18,
      "time": "2176-09-27 12:36:30",
      "speaker": "Patient",
      "text": "Yes, every day. My ulcerative colitis has been quiet lately."
    },
    {
      "turn_number": 19,
      "time": "2176-09-27 12:37:45",
      "speaker": "Doctor",
      "text": "Good. We’ll keep managing that the same way. Any asthma symptoms?"
    },
    {
      "turn_number": 20,
      "time": "2176-09-27 12:39:00",
      "speaker": "Patient",
      "text": "No, I’ve been using my inhaler as prescribed."
    },
    {
      "turn_number": 21,
      "time": "2176-09-27 12:40:15",
      "speaker": "Doctor",
      "text": "Perfect. We’ll continue your usual meds. I’ll see you tomorrow morning before the infusion."
    },
    {
      "turn_number": 22,
      "time": "2176-09-28 09:00:00",
      "speaker": "Doctor",
      "text": "Good morning. We’re ready to start your methotrexate infusion. Urine pH is above 8, so we’re safe to proceed."
    },
    {
      "turn_number": 23,
      "time": "2176-09-28 09:01:30",
      "speaker": "Patient",
      "text": "Okay, I’m ready. How long will it take?"
    },
    {
      "turn_number": 24,
      "time": "2176-09-28 09:03:00",
      "speaker": "Doctor",
      "text": "About four hours. You’ll stay in the infusion center, and we’ll monitor you closely."
    },
    {
      "turn_number": 25,
      "time": "2176-09-28 09:04:30",
      "speaker": "Patient",
      "text": "And the dose is the same as before?"
    },
    {
      "turn_number": 26,
      "time": "2176-09-28 09:06:00",
      "speaker": "Doctor",
      "text": "Yes, 13,760 mg total, based on your body surface area. It’s a high dose, but we’ve done this safely before."
    },
    {
      "turn_number": 27,
      "time": "2176-09-28 09:07:30",
      "speaker": "Patient",
      "text": "I trust you. Just hope the nausea isn’t too bad this time."
    },
    {
      "turn_number": 28,
      "time": "2176-09-28 09:09:00",
      "speaker": "Doctor",
      "text": "We’ll give you prochlorperazine at the first sign. Let the nurse know right away if you feel sick."
    },
    {
      "turn_number": 29,
      "time": "2176-09-28 13:30:00",
      "speaker": "Doctor",
      "text": "Infusion is complete. You did really well—no reactions so far."
    },
    {
      "turn_number": 30,
      "time": "2176-09-28 13:31:30",
      "speaker": "Patient",
      "text": "Thanks. I feel okay now, but I know it might hit later."
    },
    {
      "turn_number": 31,
      "time": "2176-09-28 13:33:00",
      "speaker": "Doctor",
      "text": "We’ll keep you hydrated and start leucovorin tomorrow at the same time as the infusion ended."
    },
    {
      "turn_number": 32,
      "time": "2176-09-28 20:00:00",
      "speaker": "Patient",
      "text": "Doctor, I’m starting to feel nauseated. Can I take something?"
    },
    {
      "turn_number": 33,
      "time": "2176-09-28 20:02:00",
      "speaker": "Doctor",
      "text": "Yes, let’s give you prochlorperazine now. Also try sipping water or ginger tea if you can."
    },
    {
      "turn_number": 34,
      "time": "2176-09-28 20:03:30",
      "speaker": "Patient",
      "text": "Thank you. I hate throwing up—it makes me anxious."
    },
    {
      "turn_number": 35,
      "time": "2176-09-28 20:05:00",
      "speaker": "Doctor",
      "text": "We’ll keep the lorazepam available. Try to rest. The nausea should improve in a day or two."
    },
    {
      "turn_number": 36,
      "time": "2176-09-29 08:00:00",
      "speaker": "Doctor",
      "text": "Good morning. Your methotrexate level is 0.45, which is expected. We’ve started leucovorin."
    },
    {
      "turn_number": 37,
      "time": "2176-09-29 08:01:30",
      "speaker": "Patient",
      "text": "Is that a safe level?"
    },
    {
      "turn_number": 38,
      "time": "2176-09-29 08:03:00",
      "speaker": "Doctor",
      "text": "It’s high, but we expect that. It needs to drop below 0.1. We’ll check again tomorrow."
    },
    {
      "turn_number": 39,
      "time": "2176-09-29 08:04:30",
      "speaker": "Patient",
      "text": "And my kidneys? The creatinine was good?"
    },
    {
      "turn_number": 40,
      "time": "2176-09-29 08:06:00",
      "speaker": "Doctor",
      "text": "Yes, creatinine is 0.5, even better than before. Your liver enzymes are a bit elevated but not concerning."
    },
    {
      "turn_number": 41,
      "time": "2176-09-29 08:07:30",
      "speaker": "Patient",
      "text": "That’s a relief. I was worried about that."
    },
    {
      "turn_number": 42,
      "time": "2176-09-29 14:00:00",
      "speaker": "Doctor",
      "text": "You’re doing well. Nausea better?"
    },
    {
      "turn_number": 43,
      "time": "2176-09-29 14:01:30",
      "speaker": "Patient",
      "text": "Much better. I even ate some toast and chicken."
    },
    {
      "turn_number": 44,
      "time": "2176-09-29 14:03:00",
      "speaker": "Doctor",
      "text": "Great. That means you’re recovering well. We’ll check your methotrexate level one more time tomorrow."
    },
    {
      "turn_number": 45,
      "time": "2176-09-30 06:00:00",
      "speaker": "Doctor",
      "text": "Good news—your methotrexate level is now 0.03, which is very low. Safe for discharge."
    },
    {
      "turn_number": 46,
      "time": "2176-09-30 06:01:30",
      "speaker": "Patient",
      "text": "That’s wonderful. Does that mean I can go home today?"
    },
    {
      "turn_number": 47,
      "time": "2176-09-30 06:03:00",
      "speaker": "Doctor",
      "text": "Yes. You’ll go home on oral leucovorin for a few more doses and return in a month for your next cycle."
    },
    {
      "turn_number": 48,
      "time": "2176-09-30 06:04:30",
      "speaker": "Patient",
      "text": "And my aspirin? I stopped it for the admission."
    },
    {
      "turn_number": 49,
      "time": "2176-09-30 06:06:00",
      "speaker": "Doctor",
      "text": "Yes, you can restart it today. We held it because of bleeding risk, but it’s safe now."
    },
    {
      "turn_number": 50,
      "time": "2176-09-30 06:07:30",
      "speaker": "Patient",
      "text": "Thank you, Doctor. I appreciate all your care."
    },
    {
      "turn_number": 51,
      "time": "2176-09-30 06:09:00",
      "speaker": "Doctor",
      "text": "You did great. Keep taking your meds, watch for nausea, and call if anything changes. See you next month."
    },
    {
      "turn_number": 52,
      "time": "2176-09-30 06:10:30",
      "speaker": "Patient",
      "text": "I will. Thanks again."
    },
    {
      "turn_number": 53,
      "time": "2176-09-30 06:12:00",
      "speaker": "Doctor",
      "text": "One more thing—we refilled your lorazepam prescription in case you need it for nausea or anxiety at home."
    },
    {
      "turn_number": 54,
      "time": "2176-09-30 06:13:30",
      "speaker": "Patient",
      "text": "That’s helpful. I’ll keep it on hand."
    },
    {
      "turn_number": 55,
      "time": "2176-09-30 06:15:00",
      "speaker": "Doctor",
      "text": "And your depression—how have you been feeling emotionally?"
    },
    {
      "turn_number": 56,
      "time": "2176-09-30 06:16:30",
      "speaker": "Patient",
      "text": "Okay, I think. A bit anxious around treatments, but citalopram helps."
    },
    {
      "turn_number": 57,
      "time": "2176-09-30 06:18:00",
      "speaker": "Doctor",
      "text": "That’s normal. Don’t hesitate to talk to your psychiatrist if it gets worse."
    },
    {
      "turn_number": 58,
      "time": "2176-09-30 06:19:30",
      "speaker": "Patient",
      "text": "I won’t. I’ve got support at home too."
    },
    {
      "turn_number": 59,
      "time": "2176-09-30 06:21:00",
      "speaker": "Doctor",
      "text": "That’s important. Take care of yourself. We’ll see you in four weeks."
    },
    {
      "turn_number": 60,
      "time": "2176-09-30 06:22:30",
      "speaker": "Patient",
      "text": "I’ll be ready. Thank you, Doctor."
    }
  ],
  "summary": {
    "admission_start": "2176-09-27 11:51:00",
    "admission_end": "2176-09-30 14:00:00",
    "summary_paragraph": "A 50-year-old woman with primary central nervous system lymphoma was admitted for her 23rd cycle of high-dose methotrexate chemotherapy. She reported feeling well prior to admission with no neurological symptoms, fever, or pain. Methotrexate was administered safely after urine alkalinization, and leucovorin rescue was initiated 24 hours post-infusion. She experienced nausea and vomiting during the first day after treatment but improved by discharge, tolerating a regular diet. Methotrexate levels declined appropriately to 0.03 micromolar. Her chronic conditions, including ulcerative colitis, asthma, depression, and chemotherapy-induced anemia, were stable and managed without complication. Aspirin was restarted at discharge. She was discharged home in stable condition with a short course of oral leucovorin and a plan to return in one month for her next cycle.",
    "problems": [
      "Encounter for antineoplastic chemotherapy",
      "Primary central nervous system lymphoma, unspecified site, extranodal and solid organ sites",
      "Ulcerative colitis, unspecified",
      "Nausea with vomiting",
      "Depressive disorder, not elsewhere classified",
      "Asthma, unspecified type, unspecified",
      "Pain in limb",
      "Antineoplastic chemotherapy induced anemia",
      "Personal history of pulmonary embolism",
      "Personal history of venous thrombosis and embolism",
      "Antineoplastic and immunosuppressive drugs causing adverse effects in therapeutic use",
      "Tubal ligation status"
    ]
  }
}
